/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Avatar,
  Button,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
} from '@mui/material';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
import { updateUrlParams } from '../../utils/urlUtilis';
// componentss
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

export default function IconPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const navigate = useNavigate();
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [amenityList, setAmenityList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [opens, setOpens] = useState(false);
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')

  const TABLE_HEAD = [
    { id: 'icon', label: i18?.LISTINGPAGE?.ICON || 'ICON', alignRight: false },
    { id: 'name', label: i18?.LISTINGPAGE?.NAME || 'NAME', alignRight: false },
    { id: 'label', label: i18?.LISTINGPAGE?.LABEL || 'LABEL', alignRight: false },
    { id: 'action', label: i18?.LISTINGPAGE?.ACTION || 'ACTION', alignRight: false },
  ];


  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/admin/icon?_page=${page}&_limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });
      const res = await axios.get(url);
      if (res.status === 200) {
        setAmenityList(res.data.data.icons);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const deleteModal = (ids) => {
    setOpens(true);
    sessionStorage.setItem('ids', ids);
  };

  const deleteIcon = async () => {
    const id = sessionStorage.getItem('ids');
    try {
      const res = await axios.delete(`module/admin/icon/${id}`);
      if (res.status === 200) {
        setOpens(false);
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = amenityList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'Icon';
    const action = 'Add';
    navigate('/dashboard/addicon', { state: { types: type, process: action } });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(0);
    setFilterName(event.target.value);
  };

  const columns = [
    {
      header: i18?.LISTINGPAGE?.ICON || 'ICON',
      id: "icon",
      accessorKey: "icon",
      cell: ({ row }) => (
        row?.original?.icon ? <Avatar variant="square" src={IMAGE_URL + row?.original?.icon} sx={{ width: 40, height: 40 }} /> : "---"
      )
    },
    {
      header: i18?.LISTINGPAGE?.NAME || 'NAME',
      id: "name",
      accessorKey: "name",
      showFilter: true,
      // Cell: ({ cell: { value } }) => <span>{value || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.LABEL || 'LABEL',
      id: "label",
      accessorKey: "label",
      showFilter: true,
      // Cell: ({ cell: { value } }) => <span>{value || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.ACTION || 'ACTION',
      id: "action",
      accessorKey: "_id",
      cell: ({ row }) =>
        <IconButton onClick={() => deleteModal(row?.original?._id)}>
          <Iconify icon={'eva:trash-2-outline'} />
        </IconButton>
    },
  ]

  // const columns = useMemo(() => COLUMNS, []);
  // const data = React.useMemo(() => amenityList.map((user) => {
  //   return {
  //     icon: user?.icon,
  //     name: user?.name,
  //     label: user?.label,
  //     action: user?._id,
  //   };
  // }), [amenityList]);

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> Rules | Admin panel </title>
      </Helmet>

      {isMobile && <Stack direction="row" alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.LIST_RULES || "List Rules"}
        </Typography>
        <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
          {i18?.LISTINGPAGE?.ADD_RULES || "Add Rules"}
        </Button>
      </Stack>}
      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.LIST_RULES || "List Rules"}
        </Typography>
        <div>
          <Stack direction="row" alignItems="center">
            <UserListToolbar
              numSelected={selected.length}
              filterName={filterName}
              onFilterName={handleFilterByName}
              search={search}
              setsearch={setsearch}
            />
            <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
              {i18?.LISTINGPAGE?.ADD_RULES || "Add Rules"}
            </Button>
          </Stack>
        </div>
      </Stack>}

      <Card>
        {isMobile && <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />}

        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={amenityList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>
      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={deleteIcon}
      />

    </>
  );
}
